import os, re, csv, json, numpy as np
try:
    from scipy.optimize import linear_sum_assignment
except Exception:
    linear_sum_assignment = None

N = 26
TOL = 1e-8
OUT_ROOT = 'storage/noesis/nmap/inquire_nudged'

# Baseline dirs
D_NOE = 'storage/noesis/exports/sota_243'
D_SCI_CAND = [
    'storage/Scientia/nmap/n26',
    '/home/ubuntu/station_2/station_data/rooms/research/storage/lineages/scientia/nmap/n26',
]
D_PRO_CAND = [
    'storage/Prometheus/nmap/n26',
    '/home/ubuntu/station_2/station_data/rooms/research/storage/lineages/prometheus/nmap/n26',
]
D_INQ_ROOT = 'storage/Inquire/nmap/n26'

# Extended canonicalization for boundary labels
CANON = {
  'xl':'xL','x_l':'xL','xleft':'xL','left':'xL','xmin':'xL','x_min':'xL',
  'xr':'xR','x_r':'xR','xright':'xR','right':'xR','xmax':'xR','x_max':'xR',
  'yb':'yB','y_b':'yB','ybottom':'yB','bottom':'yB','ymin':'yB','y_min':'yB',
  'yt':'yT','y_t':'yT','ytop':'yT','top':'yT','ymax':'yT','y_max':'yT',
  'xL':'xL','xR':'xR','yB':'yB','yT':'yT'
}
INT_RE = re.compile(r'[-+]?\d+')
NUM_RE = re.compile(r'[-+]?\d+(?:\.\d+)?', re.I)
SIDE_RE = re.compile(r'(xL|xR|yB|yT|xl|xr|yb|yt|left|right|top|bottom|xmin|xmax|ymin|ymax|x_min|x_max|y_min|y_max)', re.I)

def first_existing(paths):
    for p in paths:
        if os.path.exists(p): return p
    return None

def read_lines(path):
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        return f.read().strip().splitlines()

def parse_pairs_raw(path):
    rows=[]
    if not os.path.exists(path): return rows
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            try:
                i = int(float(toks[0])); j = int(float(toks[1]))
                rows.append((i, j))
            except Exception:
                continue
    return rows

def parse_boundary_raw(path):
    rows=[]
    if not os.path.exists(path): return rows
    for ln in read_lines(path):
        itoks = INT_RE.findall(ln)
        if not itoks: 
            continue
        try:
            i = int(itoks[0])
        except Exception:
            continue
        m = SIDE_RE.search(ln)
        if not m:
            continue
        s_raw = m.group(1)
        k = s_raw.replace(' ', '').replace(':','').replace(',','').replace('.','').lower()
        s = CANON.get(k, CANON.get(k.lower(), k))
        if s in ('xL','xR','yB','yT'):
            rows.append((i, s))
    return rows

def normalize_indices(rows, kind):
    # Normalize to 0-based indices
    if kind == 'pairs':
        idxs = [i for (i, _) in rows] + [j for (_, j) in rows]
    else:
        idxs = [i for (i, _) in rows]
    if not idxs:
        return set(), {'applied': False, 'mode': 'empty'}
    c0 = sum(0 <= v <= N-1 for v in idxs)
    c1 = sum(1 <= v <= N for v in idxs)
    meta = {'applied': False, 'mode': 'as-is'}
    out = set()
    if c1 > c0 and all(1 <= v <= N for v in idxs):
        meta = {'applied': True, 'mode': 'minus_one'}
        if kind == 'pairs':
            for (i, j) in rows:
                a, b = i-1, j-1
                if 0 <= a < N and 0 <= b < N and a != b:
                    u, v = (a, b) if a < b else (b, a)
                    out.add((u, v))
        else:
            for (i, s) in rows:
                a = i-1
                if 0 <= a < N:
                    out.add((a, s))
    else:
        if kind == 'pairs':
            for (i, j) in rows:
                if 0 <= i < N and 0 <= j < N and i != j:
                    u, v = (i, j) if i < j else (j, i)
                    out.add((u, v))
        else:
            for (i, s) in rows:
                if 0 <= i < N:
                    out.add((i, s))
    return out, meta

def read_centers(path):
    rows=[]
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            rows.append([float(toks[0]), float(toks[1])])
    C = np.array(rows, float)
    if C.shape != (N, 2):
        raise ValueError(f"centers shape mismatch: {path} -> {C.shape}")
    return C

def load_pack(dir_root, centers_path=None):
    pr_raw = parse_pairs_raw(os.path.join(dir_root, 'active_pairs_tol1e8.csv'))
    bd_raw = parse_boundary_raw(os.path.join(dir_root, 'active_boundary_tol1e8.csv'))
    pairs, m_pairs = normalize_indices(pr_raw, 'pairs')
    bound, m_bound = normalize_indices(bd_raw, 'bound')
    C = read_centers(centers_path) if centers_path and os.path.exists(centers_path) else None
    return {'pairs': pairs, 'bound': bound, 'centers': C, 'meta': {'pairs_norm': m_pairs, 'bound_norm': m_bound}}

def jaccard(A, B):
    I = A & B; U = A | B
    J = float(len(I))/float(len(U)) if len(U) > 0 else 1.0
    return J, len(I), len(U), len(U) - len(I)

def align_map(CA, CB):
    M = np.sum((CA[:, None, :] - CB[None, :, :])**2, axis=2)
    if linear_sum_assignment is None:
        a_idx = np.lexsort((CA[:,1], CA[:,0]))
        b_idx = np.lexsort((CB[:,1], CB[:,0]))
        P = np.zeros(N, dtype=int); P[a_idx] = b_idx
        return P
    r, c = linear_sum_assignment(M)
    P = np.zeros(N, dtype=int); P[r] = c
    return P

def map_pairs(P, S):
    T = set()
    for (i, j) in S:
        a, b = int(P[i]), int(P[j])
        if a == b:
            continue
        u, v = (a, b) if a < b else (b, a)
        T.add((u, v))
    return T

def map_bound(P, S):
    T = set()
    for (i, s) in S:
        T.add((int(P[i]), s))
    return T

def pair_report(A, B, out_dir, tag):
    # Unaligned
    Jb, Ib, Ub, Db = jaccard(A['bound'], B['bound'])
    Jp, Ip, Up, Dp = jaccard(A['pairs'], B['pairs'])
    with open(os.path.join(out_dir, f'{tag}.json'), 'w') as f:
        json.dump({"n":N,"boundary":{"jaccard":Jb,"I":Ib,"U":Ub},
                   "pairs":{"jaccard":Jp,"I":Ip,"U":Up,"D":Dp}}, f, indent=2, sort_keys=True)
    with open(os.path.join(out_dir, f'{tag}.csv'), 'w', newline='') as f:
        w = csv.writer(f); w.writerow(['n','boundary_j','I_b','U_b','pairs_j','I_p','U_p','D_p'])
        w.writerow([N,Jb,Ib,Ub,Jp,Ip,Up,Dp])

    # Aligned (A->B) if centers exist
    if A['centers'] is not None and B['centers'] is not None:
        P = align_map(A['centers'], B['centers'])
        Ab, Ap = map_bound(P, A['bound']), map_pairs(P, A['pairs'])
        Jb2, Ib2, Ub2, Db2 = jaccard(Ab, B['bound'])
        Jp2, Ip2, Up2, Dp2 = jaccard(Ap, B['pairs'])
        with open(os.path.join(out_dir, f'{tag}_aligned.json'), 'w') as f:
            json.dump({"n":N,"alignment":"hungarian",
                       "boundary":{"jaccard":Jb2,"I":Ib2,"U":Ub2},
                       "pairs":{"jaccard":Jp2,"I":Ip2,"U":Up2,"D":Dp2}}, f, indent=2, sort_keys=True)
        with open(os.path.join(out_dir, f'{tag}_aligned.csv'), 'w', newline='') as f:
            w = csv.writer(f); w.writerow(['n','alignment','boundary_j','I_b','U_b','pairs_j','I_p','U_p','D_p'])
            w.writerow([N,'hungarian',Jb2,Ib2,Ub2,Jp2,Ip2,Up2,Dp2])

def discover_inquire_packs(root):
    packs=[]
    if not os.path.exists(root):
        return packs
    # Consider root itself and its immediate subdirs
    candidates=[root] + [os.path.join(root, d) for d in os.listdir(root) if os.path.isdir(os.path.join(root,d))]
    for p in candidates:
        c=os.path.join(p,'centers.txt'); r=os.path.join(p,'radii.txt')
        b=os.path.join(p,'active_boundary_tol1e8.csv')
        if os.path.exists(c) and os.path.exists(r) and os.path.exists(b):
            name=os.path.relpath(p, root).replace(os.sep,'_') or 'root'
            packs.append((name,p))
    return packs

def construct_packing():
    os.makedirs(OUT_ROOT, exist_ok=True)

    # Load baselines
    sci_dir = first_existing(D_SCI_CAND)
    pro_dir = first_existing(D_PRO_CAND)
    if sci_dir is None:
        raise FileNotFoundError("Scientia n=26 exports not found")
    if pro_dir is None:
        print("[WARN] Prometheus n=26 not found; proceeding without it")
    noe = load_pack(D_NOE, centers_path='storage/noesis/latest_centers.txt')
    sci = load_pack(sci_dir, centers_path=os.path.join(sci_dir,'centers.txt'))
    pro = load_pack(pro_dir, centers_path=os.path.join(pro_dir,'centers.txt')) if pro_dir else None

    packs = discover_inquire_packs(D_INQ_ROOT)
    summary_rows=[]
    if not packs:
        meta={'note':'No Inquire nudged packs found','root':D_INQ_ROOT}
        with open(os.path.join(OUT_ROOT,'inquire_nudged_meta.json'),'w') as f:
            json.dump(meta,f,indent=2,sort_keys=True)
        # Return baseline unchanged
        c = np.loadtxt('storage/noesis/latest_centers.txt'); r = np.loadtxt('storage/noesis/latest_radii.txt')
        return np.array(c,float).reshape(N,2), np.array(r,float).reshape(N,)

    for name, path in packs:
        out_dir = os.path.join(OUT_ROOT, name)
        os.makedirs(out_dir, exist_ok=True)
        pack = load_pack(path, centers_path=os.path.join(path,'centers.txt'))

        # Against Noesis_243
        pair_report(pack, noe, out_dir, f'{name}_vs_noesis243_tol1e8')
        # Against Scientia_259
        pair_report(pack, sci, out_dir, f'{name}_vs_scientia259_tol1e8')
        # Against Prometheus_298 (optional)
        if pro is not None:
            pair_report(pack, pro, out_dir, f'{name}_vs_prometheus298_tol1e8')

        # For summary, load aligned boundary J if present; else unaligned
        def load_j(path_json, fallback_json):
            if os.path.exists(path_json):
                with open(path_json,'r') as f: return float(json.load(f)['boundary']['jaccard'])
            with open(fallback_json,'r') as f: return float(json.load(f)['boundary']['jaccard'])

        j_noe = load_j(os.path.join(out_dir, f'{name}_vs_noesis243_tol1e8_aligned.json'),
                       os.path.join(out_dir, f'{name}_vs_noesis243_tol1e8.json'))
        j_sci = load_j(os.path.join(out_dir, f'{name}_vs_scientia259_tol1e8_aligned.json'),
                       os.path.join(out_dir, f'{name}_vs_scientia259_tol1e8.json'))
        if pro is not None:
            j_pro = load_j(os.path.join(out_dir, f'{name}_vs_prometheus298_tol1e8_aligned.json'),
                           os.path.join(out_dir, f'{name}_vs_prometheus298_tol1e8.json'))
        else:
            j_pro = None

        summary_rows.append([name, j_noe, j_sci, '' if j_pro is None else j_pro])

    with open(os.path.join(OUT_ROOT,'inquire_nudged_summary.csv'),'w',newline='') as f:
        w=csv.writer(f); w.writerow(['pack','boundary_j_noesis243','boundary_j_scientia259','boundary_j_prometheus298'])
        for r in summary_rows: w.writerow(r)

    # Return current Noesis packing unchanged
    c = np.loadtxt('storage/noesis/latest_centers.txt'); r = np.loadtxt('storage/noesis/latest_radii.txt')
    return np.array(c,float).reshape(N,2), np.array(r,float).reshape(N,)
